ALTER TABLE fans ADD COLUMN membership_level text;

UPDATE fans f
SET membership_level = m.memb_kind
FROM (
    SELECT DISTINCT ON (member_fan_pivot) member_fan_pivot, memb_kind
    FROM membershipandspending
    ORDER BY member_fan_pivot, member_reg DESC
) m
WHERE f.user_registry = m.member_fan_pivot;

ALTER TABLE fans ADD COLUMN membership_level text;

UPDATE fans f
SET membership_level = (
    SELECT m.memb_kind 
    FROM membershipandspending m 
    WHERE m.member_fan_pivot = f.user_registry 
    ORDER BY m.member_reg DESC 
    LIMIT 1
);

ALTER TABLE fans ADD COLUMN membership_level text;

UPDATE fans f 
SET membership_level = m.memb_kind 
FROM membershipandspending m 
WHERE f.user_registry = m.member_fan_pivot 
AND m.member_reg = (
    SELECT MAX(m2.member_reg) 
    FROM membershipandspending m2 
    WHERE m2.member_fan_pivot = m.member_fan_pivot
);

ALTER TABLE fans ADD COLUMN membership_level text;

WITH latest_membership AS (
    SELECT DISTINCT ON (member_fan_pivot) member_fan_pivot, memb_kind
    FROM membershipandspending
    ORDER BY member_fan_pivot, member_reg DESC
)
UPDATE fans f
SET membership_level = lm.memb_kind
FROM latest_membership lm
WHERE f.user_registry = lm.member_fan_pivot;

